package smartracket.com.ui.theme
import androidx.compose.material3.Typography import androidx.compose.ui.text.TextStyle import androidx.compose.ui.text.font.FontFamily import androidx.compose.ui.text.font.FontWeight import androidx.compose.ui.unit.sp
/** * Samsung One font family for consistent branding across all languages. * Supports Latin, Simplified Chinese, and Traditional Chinese glyphs. */ val AppFontFamily = FontFamily( Font(R.font.SamsungOne_400, FontWeight.Normal), Font(R.font.samsungsharpsans_bold, FontWeight.Bold), Font(R.font.SamsungOne_400, FontWeight.Medium), Font(R.font.SamsungOne_700, FontWeight.SemiBold), )
/** * SmartRacket typography configuration. * * Uses Material 3 type scale with custom sizing for * training displays and analytics dashboards. * All styles use [AppFontFamily] (Noto Sans SC) for CJK compatibility. */ val Typography = Typography( // Large display for score numbers displayLarge = TextStyle( fontFamily = AppFontFamily, fontWeight = FontWeight.Bold, fontSize = 72.sp, lineHeight = 80.sp, letterSpacing = (-0.25).sp ), displayMedium = TextStyle( fontFamily = AppFontFamily, fontWeight = FontWeight.Bold, fontSize = 48.sp, lineHeight = 56.sp, letterSpacing = 0.sp ), displaySmall = TextStyle( fontFamily = AppFontFamily, fontWeight = FontWeight.SemiBold, fontSize = 36.sp, lineHeight = 44.sp, letterSpacing = 0.sp ), // Headlines for section titles headlineLarge = TextStyle( fontFamily = AppFontFamily, fontWeight = FontWeight.SemiBold, fontSize = 32.sp, lineHeight = 40.sp, letterSpacing = 0.sp ), headlineMedium = TextStyle( fontFamily = AppFontFamily, fontWeight = FontWeight.SemiBold, fontSize = 28.sp, lineHeight = 36.sp, letterSpacing = 0.sp ), headlineSmall = TextStyle( fontFamily = AppFontFamily, fontWeight = FontWeight.SemiBold, fontSize = 24.sp, lineHeight = 32.sp, letterSpacing = 0.sp ), // Titles for cards and dialogs titleLarge = TextStyle( fontFamily = AppFontFamily, fontWeight = FontWeight.Medium, fontSize = 22.sp, lineHeight = 28.sp, letterSpacing = 0.sp ), titleMedium = TextStyle( fontFamily = AppFontFamily, fontWeight = FontWeight.Medium, fontSize = 16.sp, lineHeight = 24.sp, letterSpacing = 0.15.sp ), titleSmall = TextStyle( fontFamily = AppFontFamily, fontWeight = FontWeight.Medium, fontSize = 14.sp, lineHeight = 20.sp, letterSpacing = 0.1.sp ), // Body text bodyLarge = TextStyle( fontFamily = AppFontFamily, fontWeight = FontWeight.Normal, fontSize = 16.sp, lineHeight = 24.sp, letterSpacing = 0.5.sp ), bodyMedium = TextStyle( fontFamily = AppFontFamily, fontWeight = FontWeight.Normal, fontSize = 14.sp, lineHeight = 20.sp, letterSpacing = 0.25.sp ), bodySmall = TextStyle( fontFamily = AppFontFamily, fontWeight = FontWeight.Normal, fontSize = 12.sp, lineHeight = 16.sp, letterSpacing = 0.4.sp ), // Labels for buttons and chips labelLarge = TextStyle( fontFamily = AppFontFamily, fontWeight = FontWeight.Medium, fontSize = 14.sp, lineHeight = 20.sp, letterSpacing = 0.1.sp ), labelMedium = TextStyle( fontFamily = AppFontFamily, fontWeight = FontWeight.Medium, fontSize = 12.sp, lineHeight = 16.sp, letterSpacing = 0.5.sp ), labelSmall = TextStyle( fontFamily = AppFontFamily, fontWeight = FontWeight.Medium, fontSize = 11.sp, lineHeight = 16.sp, letterSpacing = 0.5.sp ) )

